insert into rule_runtime_status(
    id, rule_id, rule_version, instance_id, status,
    hit_count, error_count, last_error, updated_at
) values (
    #{id}, #{ruleId}, 1, #{instanceId}, 'ACTIVE', 0, 0, null, current_timestamp
)

mapper.select:
select status
  from rule_runtime_status
 where id = #{id}

select status
  from rule_version
 where rule_id = #{ruleId}
   and version = #{version}

select terminal_source
  from operation_plan
 where id = #{operationId}

select status
  from rule_runtime_status
 where rule_id = #{ruleId}
   and instance_id = #{instanceId}

select status
  from operation_plan
 where id = #{operationId}

select status
  from rollout_instance_execution
 where operation_plan_id = #{operationId}

select status
  from instance
 where id = #{instanceId}

select status
  from attach_executor
 where id = #{executorId}

select status
  from attach_executor_target
 where executor_id = #{executorId}
   and instance_id = #{instanceId}

select status
  from sidecar_instance
 where id = #{sidecarId}

mapper.update:
update agent_instance
   set status = 'OFFLINE'
 where id <> #{agentId}

mapper.select:
select registration_status
  from instance
 where id = #{instanceId}

select lower(e.type)
  from environment e
 where e.id = #{environmentId}

select count(*)
  from rule
 where name = #{name}
